package dev.gbppimentel.snapcompanion.next;

import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.json.*;import android.content.Context;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33)
public class EdenLinkStoreTest {
    private Context context;private EdenLinkStore store;
    @Before public void init(){context=RuntimeEnvironment.getApplication();context.getSharedPreferences("snap-eden",0).edit().clear().commit();store=new EdenLinkStore(context);}
    private EdenPhotodex.Snapshot snapshot(){var p=new EdenPhotodex.Photo(810,1,3785,"Gold",4);return new EdenPhotodex.Snapshot(Map.of(p.key(),p),1,0);}
    @Test public void gameSyncDoesNotRewriteManualProgressOrUndo()throws Exception{Progress manual=new Progress();manual.score(810,1,100,"Bronze");manual.setPhoto(172,2,true);String before=manual.toJson();store.publish("default","A".repeat(32),"hash",snapshot());Progress effective=store.effective("default",manual);assertEquals(3785,effective.photos.get("810:1").score());assertTrue(effective.has(172,2));assertEquals(before,manual.toJson());assertEquals(100,manual.photos.get("810:1").score());}
    @Test public void rejectsDifferentEdenUserAndKeepsLastGoodData()throws Exception{store.publish("default","A".repeat(32),"hash",snapshot());assertThrows(JSONException.class,()->store.publish("default","B".repeat(32),"bad",snapshot()));assertEquals("hash",store.hash("default"));assertEquals(1,store.photos("default").size());}
    @Test public void companionProfilesDoNotShareGameResults()throws Exception{store.publish("default","A".repeat(32),"hash",snapshot());assertTrue(store.photos("second").isEmpty());assertEquals("",store.bound("second"));}
    @Test public void documentSourceRetainsRootBindingAndHistoryWithoutInventingIdentity()throws Exception{store.publish("default","A".repeat(32),"first",snapshot());var lower=new EdenPhotodex.Photo(810,1,3001,"Silver",5);store.publishDocument("default","content://granted/save","second",new EdenPhotodex.Snapshot(Map.of(lower.key(),lower),1,0));assertEquals("A".repeat(32),store.bound("default"));assertEquals("Granted save document",store.source("default"));assertEquals("content://granted/save",store.document("default"));assertEquals(2,store.history("default").length());assertEquals(3785,store.history("default").getJSONObject(1).getInt("before"));assertEquals(3001,store.history("default").getJSONObject(1).getInt("after"));}
    @Test public void malformedCacheNeverPublishesPartialRecords()throws Exception{store.publish("default","A".repeat(32),"hash",snapshot());context.getSharedPreferences("snap-eden",0).edit().putString("photos.default","[{\"id\":810,\"stars\":1,\"score\":3785,\"medal\":\"Gold\",\"image\":4},{}]").commit();assertTrue(store.photos("default").isEmpty());}
    @Test public void automaticCollectionExcludesUnverifiedLegacyWithoutDeletingIt()throws Exception{Progress legacy=new Progress();legacy.score(172,2,9000,"Diamond");legacy.completedRequests.add("hide-flowers");legacy.objectives.add("810:4");String before=legacy.toJson();store.publish("default","A".repeat(32),"hash",snapshot());Progress live=store.automatic("default",legacy);assertEquals(1,live.photos.size());assertEquals(3785,live.photos.get("810:1").score());assertFalse(live.has(172,2));assertTrue(live.completedRequests.isEmpty());assertTrue(live.objectives.contains("810:4"));assertEquals(before,legacy.toJson());}
}
